# Generated by forge. Config ratchet for Python tool configs (run by .forge/check.sh
# with the project's own Python, 3.11+): compares each changed file with its copy in
# the base and prints one line per loosened setting. Usage:
#   python ratchet.py <base-dir> <path>...
# Exit 0: nothing loosened; 1: findings printed; 3: cannot run ("skipped: …" printed).
import json
import re
import sys

try:
    import tomllib
except ImportError:
    print("skipped: tomllib needs Python 3.11+")
    sys.exit(3)

findings = []


def out(path, what):
    findings.append(f"{path}: {what}")


def show(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if v is None:
        return "unset"
    if isinstance(v, (list, tuple)):
        return "[" + ", ".join(show(x) for x in v) + "]"
    return str(v).replace('"', "").replace("\\", "/")


def as_list(v):
    if v is None:
        return []
    return list(v) if isinstance(v, (list, tuple)) else [v]


def strip_jsonc(text):
    """JSON with comments and trailing commas -> JSON."""
    out_, i, n, in_str = [], 0, len(text), False
    while i < n:
        c = text[i]
        if in_str:
            out_.append(c)
            if c == "\\" and i + 1 < n:
                out_.append(text[i + 1])
                i += 1
            elif c == '"':
                in_str = False
        elif c == '"':
            in_str = True
            out_.append(c)
        elif text.startswith("//", i):
            while i < n and text[i] != "\n":
                i += 1
            continue
        elif text.startswith("/*", i):
            end = text.find("*/", i + 2)
            i = n if end < 0 else end + 2
            continue
        else:
            out_.append(c)
        i += 1
    return re.sub(r",(\s*[}\]])", r"\1", "".join(out_))


# ---- ruff

def covered(code, selectors):
    return any(s == "ALL" or code.startswith(s) for s in selectors)


def ruff(path, before, after, prefix=""):
    def lint(cfg):
        return {**{k: v for k, v in cfg.items() if k != "lint"}, **(cfg.get("lint") or {})}

    b, a = lint(before), lint(after)
    for key in ("select", "extend-select"):
        new = as_list(a.get("select")) + as_list(a.get("extend-select"))
        for code in as_list(b.get(key)):
            if not covered(code, new):
                out(path, f"{prefix}lint.{key} no longer selects {code}")
    for key in ("ignore", "extend-ignore"):
        for code in as_list(a.get(key)):
            if code not in as_list(b.get(key)):
                out(path, f"{prefix}lint.{key} adds {code}")
    for key in ("per-file-ignores", "extend-per-file-ignores"):
        bb, aa = b.get(key) or {}, a.get(key) or {}
        for glob, codes in aa.items():
            for code in as_list(codes):
                if code not in as_list(bb.get(glob)):
                    out(path, f"{prefix}lint.{key} adds {code} for {glob}")
    for key in ("exclude", "extend-exclude"):
        for x in as_list(after.get(key)):
            if x not in as_list(before.get(key)):
                out(path, f"{prefix}{key} adds {x}")
        for x in as_list((after.get("lint") or {}).get(key)):
            if x not in as_list((before.get("lint") or {}).get(key)):
                out(path, f"{prefix}lint.{key} adds {x}")


# ---- ty

TY_LEVELS = {"ignore": 0, "warn": 1, "error": 2}


def ty(path, b, a, prefix=""):
    rb, ra = b.get("rules") or {}, a.get("rules") or {}
    for key, vb in rb.items():
        if vb not in TY_LEVELS:
            continue
        va = ra.get(key)
        if va is None and TY_LEVELS[vb] > 0:
            out(path, f"{prefix}rules.{key} {show(vb)} -> unset")
        elif va in TY_LEVELS and TY_LEVELS[va] < TY_LEVELS[vb]:
            out(path, f"{prefix}rules.{key} {show(vb)} -> {show(va)}")
    tb, ta = b.get("terminal") or {}, a.get("terminal") or {}
    if tb.get("error-on-warning") is True and ta.get("error-on-warning") is not True:
        out(path, f"{prefix}terminal.error-on-warning true -> {show(ta.get('error-on-warning'))}")
    sb, sa = b.get("src") or {}, a.get("src") or {}
    for x in as_list(sa.get("exclude")):
        if x not in as_list(sb.get("exclude")):
            out(path, f"{prefix}src.exclude adds {x}")
    if len(as_list(a.get("overrides"))) > len(as_list(b.get("overrides"))):
        out(path, f"{prefix}overrides adds an entry")


# ---- pytest

LOOSE_OPTS = re.compile(r"^(--ignore(-glob)?|--deselect|-k|-m|--continue-on-collection-errors|--lf|--last-failed|--sw|--stepwise)(=|$)")


def pytest(path, b, a, prefix):
    tb = str(b.get("addopts", "")).split() if not isinstance(b.get("addopts"), list) else b.get("addopts")
    ta = str(a.get("addopts", "")).split() if not isinstance(a.get("addopts"), list) else a.get("addopts")
    for t in ta:
        if LOOSE_OPTS.match(t) and t not in tb:
            out(path, f"{prefix}addopts adds {t}")
    for x in as_list(b.get("testpaths")):
        if x not in as_list(a.get("testpaths")):
            out(path, f"{prefix}testpaths no longer has {x}")
    for x in as_list(a.get("norecursedirs")):
        if x not in as_list(b.get("norecursedirs")):
            out(path, f"{prefix}norecursedirs adds {x}")
    if b.get("xfail_strict") is True and a.get("xfail_strict") is not True:
        out(path, f"{prefix}xfail_strict true -> {show(a.get('xfail_strict'))}")


# ---- coverage

def coverage(path, b, a, prefix):
    rb, ra = b.get("report") or {}, a.get("report") or {}
    fb, fa = rb.get("fail_under"), ra.get("fail_under")
    if isinstance(fb, (int, float)) and (not isinstance(fa, (int, float)) or fa < fb):
        out(path, f"{prefix}report.fail_under {show(fb)} -> {show(fa)}")
    for sect, key in (("run", "omit"), ("report", "omit"), ("report", "exclude_lines"), ("report", "exclude_also")):
        for x in as_list((a.get(sect) or {}).get(key)):
            if x not in as_list((b.get(sect) or {}).get(key)):
                out(path, f"{prefix}{sect}.{key} adds {x}")


def load(text, path):
    if path.endswith(".json"):
        return json.loads(strip_jsonc(text))
    return tomllib.loads(text)


def main():
    base = sys.argv[1]
    for path in sys.argv[2:]:
        name = path.rsplit("/", 1)[-1]
        if name not in ("pyproject.toml", "ruff.toml", ".ruff.toml", "ty.toml"):
            continue
        try:
            with open(f"{base}/{path}", encoding="utf-8") as f:
                before = load(f.read(), path)
        except FileNotFoundError:
            continue
        except (ValueError, tomllib.TOMLDecodeError):
            continue
        try:
            with open(path, encoding="utf-8") as f:
                after = load(f.read(), path)
        except (ValueError, tomllib.TOMLDecodeError) as e:
            out(path, f"cannot be parsed ({str(e).splitlines()[0]})")
            continue
        if name == "pyproject.toml":
            tb, ta = before.get("tool") or {}, after.get("tool") or {}
            ruff(path, tb.get("ruff") or {}, ta.get("ruff") or {}, "tool.ruff.")
            ty(path, tb.get("ty") or {}, ta.get("ty") or {}, "tool.ty.")
            pytest(path, (tb.get("pytest") or {}).get("ini_options") or {}, (ta.get("pytest") or {}).get("ini_options") or {}, "tool.pytest.ini_options.")
            coverage(path, tb.get("coverage") or {}, ta.get("coverage") or {}, "tool.coverage.")
        elif name == "ty.toml":
            ty(path, before, after)
        else:
            ruff(path, before, after)
    for f in findings:
        print(f)
    sys.exit(1 if findings else 0)


try:
    main()
except SystemExit:
    raise
except Exception as e:  # never report a crash as a loosened setting
    print(f"skipped: the ratchet could not run ({type(e).__name__}: {e})")
    sys.exit(3)
